function parseCookieHeader(header) {
  const jar = {};
  for (const part of header.split(";")) {
    const pair = part.trim();
    if (pair === "") continue;
    const at = pair.indexOf("=");
    if (at === -1) continue;
    jar[pair.slice(0, at)] = pair.slice(at + 1);
  }
  return jar;
}

