function sessionCookie(id, { maxAgeSeconds = 3600 } = {}) {
  if (!/^[0-9a-f]{64}$/.test(id)) throw new Error("bad session id");
  return `session=${id}; HttpOnly; Secure; SameSite=Lax; Path=/; Max-Age=${maxAgeSeconds}`;
}

