function sameSite(a, b) {
  const site = (href) => {
    const url = new URL(href);
    return `${url.protocol}//${url.hostname.split(".").slice(-2).join(".")}`;
  };
  return site(a) === site(b);
}

console.log(sameSite("https://app.tasks.example", "https://api.tasks.example:8443"));
console.log(sameSite("http://localhost:5173", "http://localhost:3000"));
